import'package:dio/dio.dart';import'offline_store.dart';import'payload_cipher.dart';
typedef TicketConfirmed=Future<void>Function(Map<String,dynamic>ticket);
class SyncEngine{SyncEngine({required this.store,required this.cipher,required this.http,required this.deviceId,this.onTicketConfirmed});final OfflineStore store;final PayloadCipher cipher;final Dio http;final String deviceId;final TicketConfirmed?onTicketConfirmed;bool _running=false;Future<void>run()async{if(_running)return;_running=true;try{final rows=store.ready();if(rows.isEmpty)return;final mutations=<Map<String,dynamic>>[];for(final row in rows){final payload=await cipher.decrypt(row['encrypted_payload']as String);mutations.add({...payload,'clientMutationId':row['id'],'operation':row['operation'],'createdAt':row['created_at']});}final response=await http.post<Map<String,dynamic>>('/api/v1/sync/batch',data:{'deviceId':deviceId,'mutations':mutations}),results=(response.data?['results']as List<dynamic>?)??[];for(final item in results){final result=item as Map<String,dynamic>,id=result['clientMutationId']as String,status=result['status'];if(status=='APPLIED'){store.applied(id);final entityId=result['serverEntityId']?.toString();if(entityId!=null&&onTicketConfirmed!=null){try{final ticket=await http.get<Map<String,dynamic>>('/api/v1/tickets/$entityId');await onTicketConfirmed!(ticket.data!);}catch(_){store.printAttention(id);/* The sale is applied; manual print follow-up is required. */}}}else if(status=='REJECTED'||status=='CONFLICT')store.rejected(id,result['errorCode']?.toString()??status.toString());}}on DioException catch(error){for(final row in store.ready())store.retry(row['id']as String,(row['attempts']as int)+1,'HTTP_${error.response?.statusCode??error.type.name}');}finally{_running=false;}}}
